import { describe, it, expect, vi } from 'vitest';
import { decompress } from 'compress-json';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

const stored: Record<string, string> = {};

vi.mock('~/utils/redis/client', () => ({
  getClient: () => ({
    get: async (key: string) => stored[key] ?? null,
    setnx: async (key: string, value: string) => { stored[key] = value; return 1; },
    set: async (key: string, value: string) => { stored[key] = value; return 'OK'; },
    expire: async () => 1,
    ttl: async () => 3600,
  }),
}));

import messageStore from '~/utils/redis/messageStore';
import { IS_COMPONENTS_V2_FLAG } from '~/constants';
import { author } from '~/utils/__tests__/helpers/discord';

describe('the dropped-set report is written alongside data (a redis StoredMessage write)', () => {
  it('persists components, the copied flag bit, and the dropped-type report from a bot Get Message payload', async () => {
    const { code } = await messageStore.store('user-1', 'guild-1', {
      id: 'msg-1',
      author: author(),
      content: '',
      embeds: [],
      flags: IS_COMPONENTS_V2_FLAG,
      components: [
        { type: 3, custom_id: 'pick', options: [] },
        { type: 10, content: 'kept' },
      ],
      channel_id: 'chan-1',
    } as never);

    const raw = stored[`get-message-${code}`];
    const record = decompress(JSON.parse(raw) as Parameters<typeof decompress>[0]) as StoredMessage;

    expect(record.data.components).toEqual([{ type: 10, content: 'kept' }]);
    expect(record.data.flags).toBe(IS_COMPONENTS_V2_FLAG);
    expect(record.droppedComponentTypes).toEqual(['Select Menu']);
  });
});
